        combined.reserveCapacity(446)
        for group in [
            knightTalents,
            rangerTalents,
            rogueTalents,
            wizardTalents,
            druidTalents,
            warlockTalents,
            alchemistTalents,
            wildcardTalents,
            wolfTalents,
            bearTalents,
            frostWhelpTalents,
            lizardScoutTalents,
            pantherTalents,
            phoenixTalents,
            goldenRetrieverTalents,
            libraryOwlTalents,
            risenSkeletonTalents,
            manaMothTalents,
            pixieTalents,
            shieldScarabTalents,
            foxTalents
        ] {
            for (key, value) in group {
                combined[key] = value
            }
        }
        return combined
    }()
}

